const peso = n => new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(n);
const state={role:null,page:'dashboard',payments:[
 {ref:'PAY-1029',borrower:'Angela Reyes',loan:'LN-2026-014',date:'Nov 16, 2026',amount:1500,method:'GCash gateway',status:'Verified'},
 {ref:'PAY-1028',borrower:'Ramon Dela Cruz',loan:'LN-2026-011',date:'Nov 15, 2026',amount:2000,method:'Cash',status:'Verified'},
 {ref:'PAY-1027',borrower:'Liza Mercado',loan:'LN-2026-008',date:'Nov 14, 2026',amount:1250,method:'GCash gateway',status:'Review'},
 {ref:'PAY-1026',borrower:'Joel Ramos',loan:'LN-2026-016',date:'Nov 13, 2026',amount:1800,method:'Bank transfer',status:'Verified'}],
 expenses:[{date:'Nov 17, 2026',category:'Office utilities',detail:'Internet and electricity',amount:6200},{date:'Nov 12, 2026',category:'Operations',detail:'Transport and field collection',amount:3400},{date:'Nov 5, 2026',category:'Supplies',detail:'Paper and printer supplies',amount:1850}],
 tapal:[{date:'Nov 10, 2026',financier:'Carlos Lim',reason:'Payout shortfall coverage',amount:12000,status:'For reimbursement'},{date:'Oct 28, 2026',financier:'Mila Tan',reason:'Temporary payout coverage',amount:8000,status:'Reimbursed'}]};

const roles={
 manager:{name:'Mara Santos',label:'Manager',initial:'M',nav:[['dashboard','▦','Dashboard'],['loans','◫','Loans & schedules'],['collections','✓','Collections'],['financiers','◇','Financier agreements'],['tapal','↗','Manager advances'],['expenses','−','Expenses'],['reports','▤','Reports'],['logs','⌁','Transaction logs'],['scope','ⓘ','Scope notes']]},
 borrower:{name:'Angela Reyes',label:'Borrower',initial:'A',nav:[['dashboard','▦','My loan'],['schedule','◫','Repayment schedule'],['history','✓','Payment history'],['scope','ⓘ','About this demo']]},
 financier:{name:'Carlos Lim',label:'Financier',initial:'C',nav:[['dashboard','▦','Investment overview'],['agreements','◇','My agreement'],['payouts','✓','Payout history'],['scope','ⓘ','About this demo']]}
};
const loans=[
 {id:'LN-2026-014',name:'Angela Reyes',principal:15000,balance:8500,rate:'4% monthly',next:'Nov 25, 2026',due:1500,status:'Current'},
 {id:'LN-2026-011',name:'Ramon Dela Cruz',principal:25000,balance:12000,rate:'3.5% monthly',next:'Nov 20, 2026',due:2000,status:'Due soon'},
 {id:'LN-2026-008',name:'Liza Mercado',principal:12000,balance:4750,rate:'4% monthly',next:'Nov 14, 2026',due:1250,status:'Overdue'},
 {id:'LN-2026-016',name:'Joel Ramos',principal:20000,balance:16400,rate:'3% monthly',next:'Nov 28, 2026',due:1800,status:'Current'}
];
const schedule=[['NOV','25','Installment 5 of 10',1500,'Upcoming'],['DEC','10','Installment 6 of 10',1500,'Scheduled'],['DEC','25','Installment 7 of 10',1500,'Scheduled'],['JAN','10','Installment 8 of 10',1500,'Scheduled']];
const financiers=[{name:'Carlos Lim',capital:100000,terms:'Fixed 5% monthly',next:5000,date:'Nov 30, 2026',status:'Active'},{name:'Mila Tan',capital:75000,terms:'Fixed 4% monthly',next:3000,date:'Nov 30, 2026',status:'Active'},{name:'Noel Garcia',capital:50000,terms:'Per signed agreement',next:2250,date:'Dec 5, 2026',status:'Review'}];

document.querySelectorAll('[data-login]').forEach(b=>b.onclick=()=>login(b.dataset.login));
document.querySelector('#roleSwitch').onclick=logout;
document.querySelector('#menuBtn').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');
document.querySelector('[data-close]').onclick=closeModal;
document.querySelector('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};

function login(role){state.role=role;state.page='dashboard';document.querySelector('#login').classList.add('hidden');document.querySelector('#app').classList.remove('hidden');renderNav();render();}
function logout(){state.role=null;document.querySelector('#app').classList.add('hidden');document.querySelector('#login').classList.remove('hidden');document.querySelector('.sidebar').classList.remove('open');}
function renderNav(){const r=roles[state.role];document.querySelector('#profileName').textContent=r.name;document.querySelector('#profileRole').textContent=r.label;document.querySelector('#profileInitial').textContent=r.initial;document.querySelector('#nav').innerHTML=r.nav.map(n=>`<button class="nav-item ${state.page===n[0]?'active':''}" data-page="${n[0]}"><span class="nav-icon">${n[1]}</span>${n[2]}</button>`).join('');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;renderNav();render();document.querySelector('.sidebar').classList.remove('open')});}
function render(){const names={dashboard:'Dashboard',loans:'Loans & schedules',collections:'Collections & verification',financiers:'Financier agreements',tapal:'Manager advances',expenses:'Business expenses',reports:'Financial reports',logs:'Transaction logs',scope:'Scope & assumptions',schedule:'Repayment schedule',history:'Payment history',agreements:'Return agreement',payouts:'Payout history'};document.querySelector('#pageTitle').textContent=names[state.page];document.querySelector('#breadcrumb').textContent=`${roles[state.role].label} workspace / ${names[state.page]}`;const key=`${state.role}_${state.page}`;document.querySelector('#content').innerHTML=(views[key]||views[`${state.role}_dashboard`])();bindActions();}
const status=s=>`<span class="status ${s==='Verified'||s==='Current'||s==='Active'||s==='Paid'||s==='Reimbursed'?'good':s==='Overdue'||s==='Failed'?'bad':s==='Review'||s==='Due soon'||s==='For reimbursement'?'warn':'info'}">${s}</span>`;
const table=(heads,rows)=>`<div class="table-wrap"><table class="data-table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const metric=(l,v,t,w='')=>`<div class="metric"><span class="label">${l}</span><div class="value">${v}</div><span class="trend ${w}">${t}</span></div>`;
const views={
 manager_dashboard:()=>`<section class="hero"><div><span class="date">WEDNESDAY · NOVEMBER 18, 2026</span><h3>Good morning, Mara.</h3><p>Here is the corporation's fictional operating snapshot.</p></div><div class="hero-actions"><button class="btn btn-primary" data-action="paymentLink">+ Payment link</button><button class="btn btn-outline" data-page-jump="reports">View reports</button></div></section><div class="metric-grid">${metric('Active loan balance',peso(41650),'4 active accounts')}${metric('Collected this month',peso(42750),'86% of monthly target')}${metric('Financier obligations',peso(10250),'Next payout: Nov 30')}${metric('Items needing review','3','1 overdue · 2 unverified','warn')}</div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h3>Cash movement</h3><p>Collections versus recorded outflows</p></div><select class="select"><option>Last 6 months</option></select></div><div class="chart">${[58,67,54,76,70,88].map((n,i)=>`<div class="bar-group"><i class="bar" style="height:${n}%"></i><i class="bar alt" style="height:${n-18}%"></i><span class="bar-label">${['Jun','Jul','Aug','Sep','Oct','Nov'][i]}</span></div>`).join('')}</div><div class="chart-legend"><span><i class="legend-dot"></i>Collections</span><span><i class="legend-dot alt"></i>Expenses & payouts</span></div></section><section class="panel"><div class="panel-head"><div><h3>Recent activity</h3><p>Latest recorded actions</p></div></div>${activity('✓','Payment verified','Angela Reyes · ₱1,500','Today, 9:42 AM')}${activity('↗','Advance recorded','Carlos Lim payout coverage','Nov 10, 2:15 PM')}${activity('−','Expense added','Internet and electricity','Nov 17, 4:20 PM')}${activity('◇','Payout scheduled','Mila Tan · ₱3,000','Nov 15, 11:05 AM')}</section></div>`,
 manager_loans:()=>`${sectionHead('Loans & repayment schedules','Monitor balances and agreed installment dates.','<button class="btn btn-dark" data-action="newLoan">+ Record loan</button>')}<div class="summary-strip"><div class="summary-item"><span>Original principal</span><b>${peso(72000)}</b></div><div class="summary-item"><span>Outstanding balance</span><b>${peso(41650)}</b></div><div class="summary-item"><span>Overdue balance</span><b>${peso(1250)}</b></div></div><section class="panel">${table(['Loan / borrower','Principal','Balance','Interest basis','Next installment','Status'],loans.map(l=>`<tr><td><div class="person"><span class="avatar">${l.name[0]}</span><span><b>${l.name}</b><br><small>${l.id}</small></span></div></td><td>${peso(l.principal)}</td><td class="money">${peso(l.balance)}</td><td>${l.rate}</td><td>${l.next}<br><b>${peso(l.due)}</b></td><td>${status(l.status)}</td></tr>`))}</section>`,
 manager_collections:()=>`${sectionHead('Collections & verification','Match payment records to borrower accounts.','<button class="btn btn-dark" data-action="paymentLink">Generate payment link</button>')}<div class="notice"><b>Simulated gateway workflow:</b> GCash confirmation below is a prototype event from a hypothetical supported provider. Personal GCash screenshots are not automatically verified.</div><section class="panel">${table(['Reference','Borrower / loan','Date','Method','Amount','Status'],state.payments.map(p=>`<tr><td><b>${p.ref}</b></td><td>${p.borrower}<br><small>${p.loan}</small></td><td>${p.date}</td><td>${p.method}</td><td class="money">${peso(p.amount)}</td><td>${status(p.status)}</td></tr>`))}</section>`,
 manager_financiers:()=>`${sectionHead('Financier agreements','Track each contribution and its individually recorded return terms.','<button class="btn btn-dark" data-action="agreement">+ Add agreement</button>')}<div class="notice">Return calculations shown here are fictional examples and depend on the signed agreement. The system does not promise investment returns.</div><section class="panel">${table(['Financier','Capital contribution','Return terms','Next expected payout','Date','Status'],financiers.map(f=>`<tr><td><div class="person"><span class="avatar">${f.name[0]}</span><b>${f.name}</b></div></td><td class="money">${peso(f.capital)}</td><td>${f.terms}</td><td class="money">${peso(f.next)}</td><td>${f.date}</td><td>${status(f.status)}</td></tr>`))}</section>`,
 manager_tapal:()=>`${sectionHead('Manager advances / tapal','Keep personal shortfall coverage separate from income and expenses.','<button class="btn btn-dark" data-action="tapal">+ Record advance</button>')}<div class="metric-grid">${metric('Open advances',peso(12000),'1 item for reimbursement')}${metric('Reimbursed this month',peso(8000),'Recorded Oct 28')}${metric('Total advanced',peso(20000),'Across 2 entries')}${metric('Accounting treatment','Separate','Not business income')}</div><section class="panel">${table(['Date','Financier','Purpose','Amount','Status'],state.tapal.map(x=>`<tr><td>${x.date}</td><td><b>${x.financier}</b></td><td>${x.reason}</td><td class="money">${peso(x.amount)}</td><td>${status(x.status)}</td></tr>`))}</section>`,
 manager_expenses:()=>`${sectionHead('Business expenses','Record operating costs without mixing them with loan principal.','<button class="btn btn-dark" data-action="expense">+ Add expense</button>')}<div class="summary-strip"><div class="summary-item"><span>November expenses</span><b>${peso(state.expenses.reduce((a,b)=>a+b.amount,0))}</b></div><div class="summary-item"><span>Largest category</span><b>Utilities</b></div><div class="summary-item"><span>Entries this month</span><b>${state.expenses.length}</b></div></div><section class="panel">${table(['Date','Category','Description','Amount'],state.expenses.map(x=>`<tr><td>${x.date}</td><td><b>${x.category}</b></td><td>${x.detail}</td><td class="money">${peso(x.amount)}</td></tr>`))}</section>`,
 manager_reports:()=>`${sectionHead('Financial reports','Presentation summaries for review and audit preparation.','<button class="btn btn-dark no-print" data-action="print">Print report</button>')}<div class="print-only"><h1>Emergency Lending Corporation — Financial Summary</h1><p>Fictional demonstration data · November 2026</p></div><div class="notice"><b>Reporting support only.</b> These summaries are not a certified audit and do not claim BIR compliance. Figures should be checked against authorized source records.</div><div class="metric-grid">${metric('Borrower collections',peso(42750),'Principal + interest + penalties')}${metric('Principal component',peso(32000),'Excluded from profit')}${metric('Interest & penalties',peso(10750),'Illustrative income component')}${metric('Operating expenses',peso(11450),'Recorded expense entries')}</div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h3>November funds summary</h3><p>Separation of money flows</p></div></div>${table(['Category','Inflow','Outflow'],[['Borrower principal','₱32,000.00','—'],['Interest & penalties','₱10,750.00','—'],['Financier payouts','—','₱10,250.00'],['Business expenses','—','₱11,450.00'],['Manager advance','₱12,000.00','—']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td></tr>`))}</section><section class="panel"><div class="panel-head"><div><h3>Report readiness</h3><p>Records requiring attention</p></div></div>${activity('!','Overdue installment','Liza Mercado · ₱1,250','4 days overdue')}${activity('?','Payment for review','PAY-1027 · evidence pending','Nov 14')}${activity('↗','Advance unreimbursed','Carlos Lim · ₱12,000','Nov 10')}</section></div>`,
 manager_logs:()=>`${sectionHead('Transaction logs','Trace demo actions and corrections without deleting history.','')}<section class="panel">${table(['Time','Actor','Action','Record','Result'],[['Today, 9:42 AM','Mara Santos','Verified payment','PAY-1029',status('Verified')],['Nov 17, 4:20 PM','Mara Santos','Added expense','EXP-0214',status('Verified')],['Nov 15, 11:05 AM','System','Scheduled payout','PO-0118',status('Active')],['Nov 14, 3:18 PM','Mara Santos','Flagged payment','PAY-1027',status('Review')]].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`))}</section>`,
 borrower_dashboard:()=>`<section class="hero"><div><span class="date">BORROWER ACCOUNT · LN-2026-014</span><h3>Hello, Angela.</h3><p>Your personal loan summary and upcoming installment.</p></div><div class="hero-actions"><button class="btn btn-primary" data-action="borrowerPay">Pay installment</button></div></section><div class="grid-2" style="margin-top:20px"><section class="loan-card"><span class="balance-label">Remaining loan balance</span><div class="big-money">${peso(8500)}</div><div class="progress"><i style="width:43%"></i></div><p style="font-size:11px;color:var(--muted)">₱6,500 of ₱15,000 principal recorded as repaid</p><div class="summary-strip"><div class="summary-item"><span>Next installment</span><b>${peso(1500)}</b></div><div class="summary-item"><span>Due date</span><b>Nov 25</b></div><div class="summary-item"><span>Account status</span><b>Current</b></div></div></section><section class="panel"><div class="panel-head"><div><h3>Loan details</h3><p>Based on fictional signed terms</p></div></div><div class="agreement"><p><b>Principal:</b> ₱15,000.00</p><p><b>Interest basis:</b> 4% monthly</p><p><b>Installments:</b> 10 scheduled</p><p><b>Current penalty:</b> ₱0.00</p></div></section></div><section class="panel" style="margin-top:18px"><div class="panel-head"><div><h3>Upcoming schedule</h3><p>Only your own loan account is visible</p></div><button class="link-btn" data-page-jump="schedule">View all</button></div>${scheduleRows(schedule.slice(0,3))}</section>`,
 borrower_schedule:()=>`${sectionHead('Repayment schedule','Dates and amounts recorded for loan LN-2026-014.','')}<div class="notice">Amounts are based on fictional demo terms. Actual interest, installment, grace-period, and penalty rules must be confirmed with the manager and signed agreement.</div><section class="panel">${scheduleRows(schedule)}</section><section class="panel"><div class="panel-head"><div><h3>Interest & penalties</h3></div></div><div class="summary-strip"><div class="summary-item"><span>Interest basis</span><b>4% monthly</b></div><div class="summary-item"><span>Late penalty</span><b>₱50 / day</b></div><div class="summary-item"><span>Current penalty</span><b>₱0.00</b></div></div></section>`,
 borrower_history:()=>`${sectionHead('Payment history','Verified entries recorded against your loan.','')}<section class="panel">${table(['Reference','Date','Method','Amount','Status'],[['PAY-1029','Nov 16, 2026','GCash gateway',1500,'Verified'],['PAY-1014','Oct 31, 2026','Cash',1500,'Verified'],['PAY-0997','Oct 15, 2026','Bank transfer',1500,'Verified'],['PAY-0980','Sep 30, 2026','Cash',1500,'Verified']].map(r=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td>${r[2]}</td><td class="money">${peso(r[3])}</td><td>${status(r[4])}</td></tr>`))}</section>`,
 financier_dashboard:()=>`<section class="hero"><div><span class="date">FINANCIER ACCOUNT · FA-2026-003</span><h3>Welcome back, Carlos.</h3><p>Your private contribution and payout overview.</p></div></section><div class="metric-grid">${metric('Recorded contribution',peso(100000),'Agreement FA-2026-003')}${metric('Agreed return','5% monthly','Illustrative fixed-return term')}${metric('Next expected payout',peso(5000),'Due Nov 30, 2026')}${metric('Paid to date',peso(45000),'9 recorded payouts')}</div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h3>Agreement summary</h3><p>Visible only to this financier and manager</p></div></div><div class="agreement"><p><b>Effective date:</b> March 1, 2026</p><p><b>Recorded capital:</b> ₱100,000.00</p><p><b>Return structure:</b> Fixed 5% monthly</p><p><b>Scheduled payout:</b> Last banking day monthly</p></div></section><section class="panel"><div class="panel-head"><div><h3>Recent payouts</h3></div><button class="link-btn" data-page-jump="payouts">View all</button></div>${activity('✓','October payout','₱5,000 · PO-0111','Oct 31, 2026')}${activity('✓','September payout','₱5,000 · PO-0104','Sep 30, 2026')}${activity('✓','August payout','₱5,000 · PO-0096','Aug 31, 2026')}</section></div>`,
 financier_agreements:()=>`${sectionHead('My return agreement','Recorded terms for agreement FA-2026-003.','')}<div class="notice">This is fictional prototype data. It does not constitute an investment offer, guaranteed return, or legally binding agreement.</div><section class="panel"><div class="agreement"><h3>Contribution and return terms</h3><p><b>Financier:</b> Carlos Lim</p><p><b>Capital contribution:</b> ₱100,000.00</p><p><b>Return calculation:</b> ₱100,000 × 5% = ₱5,000 monthly</p><p><b>Term:</b> March 1, 2026 to February 28, 2027</p><p><b>Payout schedule:</b> Last banking day of each month</p><p><b>Next review date:</b> February 15, 2027</p></div></section>`,
 financier_payouts:()=>`${sectionHead('Payout history','Completed and expected payouts for your agreement.','')}<section class="panel">${table(['Payout reference','Period','Expected','Paid','Date','Status'],[['PO-0118','November 2026',5000,0,'Nov 30, 2026','Scheduled'],['PO-0111','October 2026',5000,5000,'Oct 31, 2026','Paid'],['PO-0104','September 2026',5000,5000,'Sep 30, 2026','Paid'],['PO-0096','August 2026',5000,5000,'Aug 31, 2026','Paid']].map(r=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td>${peso(r[2])}</td><td class="money">${peso(r[3])}</td><td>${r[4]}</td><td>${status(r[5])}</td></tr>`))}</section>`,
 manager_scope:scopeView,borrower_scope:scopeView,financier_scope:scopeView
};

function sectionHead(t,p,a){return `<div class="section-head"><div><h3>${t}</h3><p>${p}</p></div><div class="toolbar">${a}</div></div>`}
function activity(i,t,p,d){return `<div class="activity"><span class="activity-icon">${i}</span><div><b>${t}</b><p>${p}</p><time>${d}</time></div></div>`}
function scheduleRows(rows){return `<div class="schedule-list">${rows.map(r=>`<div class="schedule-row"><div class="date-box"><small>${r[0]}</small><b>${r[1]}</b></div><div><b>${r[2]}</b><br><small>${r[4]}</small></div><strong>${peso(r[3])}</strong></div>`).join('')}</div>`}
function scopeView(){return `${sectionHead('Scope, assumptions & safeguards','What this prototype represents — and what it does not.','')}<div class="notice"><b>Proposal status:</b> The system concept is accepted for study, but detailed workflows and calculation rules remain tentative until manager interview and authorized record review.</div><div class="scope-grid"><div class="scope-card"><b>✓ Included in prototype</b><p>Role-based access, loan balances and schedules, verified payment records, financier agreements and payouts, manager advances, expenses, summaries, transaction logs, and printable reporting.</p></div><div class="scope-card"><b>~ Simulated only</b><p>Payment-link sharing through Messenger and GCash gateway confirmation. No funds move, no external account is contacted, and no screenshot is treated as automatic proof.</p></div><div class="scope-card"><b>× Explicitly excluded</b><p>Loan approval decisions, certified audits, guaranteed BIR compliance, payroll, advanced forecasting, and actual gateway integration.</p></div><div class="scope-card"><b>Assumed for demo</b><p>Sample interest, installment, penalty, return, reimbursement, and reporting rules are fictional PHP-denominated examples pending validation.</p></div><div class="scope-card"><b>Access isolation</b><p>Borrowers see only their own loan. Financiers see only their own agreement and payouts. Business-wide records remain in the manager workspace.</p></div><div class="scope-card"><b>Study 3 citation note</b><p>The proposal matrix and references cite Mwangi and Oscar (2023), but Section 6 describes Ratan et al. (2012). This mismatch should be corrected in supporting documentation.</p></div></div>`}

function bindActions(){document.querySelectorAll('[data-page-jump]').forEach(b=>b.onclick=()=>{state.page=b.dataset.pageJump;renderNav();render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action]?.())}
const actions={
 paymentLink(){openModal(`<span class="kicker">SIMULATED COLLECTION</span><h2>Generate payment link</h2><p style="color:var(--muted)">Create a fictional request to copy and send manually through Messenger.</p><div class="form-grid"><div class="field full"><label>Borrower / loan</label><select class="select" id="payBorrower">${loans.map(l=>`<option value="${l.id}">${l.name} — ${l.id}</option>`).join('')}</select></div><div class="field"><label>Amount</label><input class="input" id="payAmount" value="1500"></div><div class="field"><label>Expires</label><select class="select"><option>24 hours</option><option>48 hours</option></select></div></div><div class="gateway"><div class="gateway-head"><b>Gateway</b><span class="gcash">GCash · SIMULATED</span></div><p style="font-size:11px;color:var(--muted)">Automatic posting occurs only after a hypothetical supported provider confirmation.</p></div><button class="btn btn-dark" id="generateBtn">Generate demo link</button><div id="linkResult"></div>`);setTimeout(()=>document.querySelector('#generateBtn').onclick=generateLink)},
 borrowerPay(){actions.paymentLink()},newLoan(){simpleForm('Record a demo loan','Loan recording is included for presentation, but approval decisions remain outside system scope.')},agreement(){simpleForm('Add financier agreement','Return terms must come from a signed agreement and are not guaranteed by the system.')},
 tapal(){entryForm('Record manager advance','Financier','Carlos Lim','Purpose','Payout shortfall coverage','tapal')},expense(){entryForm('Add business expense','Category','Operations','Description','Demo expense entry','expense')},print(){window.print()}
};
function generateLink(){const amt=Number(document.querySelector('#payAmount').value)||1500;document.querySelector('#linkResult').innerHTML=`<p style="font-size:11px;font-weight:700;margin-top:18px">Copy into Messenger</p><div class="mock-link">https://pay.demo.local/request/ELC-${Date.now().toString().slice(-6)}</div><p style="font-size:11px;color:var(--muted)">Amount: ${peso(amt)} · This URL cannot accept real payment.</p><button class="btn btn-primary" id="copyBtn">Copy link</button> <button class="btn btn-soft" id="simulateBtn">Simulate GCash confirmation</button>`;document.querySelector('#copyBtn').onclick=()=>toast('Demo link copied for Messenger');document.querySelector('#simulateBtn').onclick=()=>{state.payments.unshift({ref:`PAY-${1030+state.payments.length}`,borrower:'Angela Reyes',loan:'LN-2026-014',date:'Nov 18, 2026',amount:amt,method:'GCash gateway',status:'Verified'});closeModal();toast('Simulated provider confirmation received — payment recorded')};}
function simpleForm(title,note){openModal(`<h2>${title}</h2><div class="notice">${note}</div><div class="form-grid"><div class="field"><label>Reference</label><input class="input" value="DEMO-${Date.now().toString().slice(-4)}"></div><div class="field"><label>Amount</label><input class="input" value="10000"></div><div class="field full"><label>Notes</label><input class="input" value="Fictional presentation record"></div></div><br><button class="btn btn-dark" id="saveSimple">Save demo record</button>`);setTimeout(()=>document.querySelector('#saveSimple').onclick=()=>{closeModal();toast('Demo record saved locally')})}
function entryForm(title,l1,v1,l2,v2,type){openModal(`<h2>${title}</h2><div class="form-grid"><div class="field"><label>${l1}</label><input id="e1" class="input" value="${v1}"></div><div class="field"><label>Amount</label><input id="ea" class="input" value="2500"></div><div class="field full"><label>${l2}</label><input id="e2" class="input" value="${v2}"></div></div><br><button class="btn btn-dark" id="saveEntry">Save entry</button>`);setTimeout(()=>document.querySelector('#saveEntry').onclick=()=>{const a=Number(document.querySelector('#ea').value)||0;if(type==='expense')state.expenses.unshift({date:'Nov 18, 2026',category:document.querySelector('#e1').value,detail:document.querySelector('#e2').value,amount:a});else state.tapal.unshift({date:'Nov 18, 2026',financier:document.querySelector('#e1').value,reason:document.querySelector('#e2').value,amount:a,status:'For reimbursement'});closeModal();render();toast('Entry saved to this local demo session')})}
function openModal(html){document.querySelector('#modalBody').innerHTML=html;document.querySelector('#modal').classList.remove('hidden')}
function closeModal(){document.querySelector('#modal').classList.add('hidden')}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}
